package sentinel.application;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import sentinel.analysis.*;
import sentinel.data.*;
import sentinel.domain.*;
import sentinel.events.*;
import sentinel.llm.*;
import sentinel.persistence.*;
import sentinel.planning.*;
import sentinel.reporting.*;
import sentinel.tools.*;
class CompletionWorkflowTest {
    @TempDir Path temp;
    DatasetStore store;ToolExecutor tools;AgentEngine engine;AgentController c;AtomicInteger calls;
    final Instant time=Instant.parse("2026-10-22T12:00:00Z");
    String mode="valid";
    @BeforeEach void init(){
        store=new DatasetStore("demo",Clock.fixed(Instant.parse("2026-10-29T12:00:00Z"),ZoneOffset.UTC),Duration.ofDays(30));tools=ToolExecutor.local(store);calls=new AtomicInteger();
        LLMGateway llm=p->{int n=calls.incrementAndGet();if(mode.equals("offline"))throw new ModelException(ModelException.Code.UNAVAILABLE,"Unavailable");
            @SuppressWarnings("unchecked") var input=(Map<String,Object>)JsonCodec.tree(p.content().substring(p.content().indexOf("DATA=")+5));
            @SuppressWarnings("unchecked") var evidence=(List<Map<String,Object>>)input.get("evidence");UUID id=UUID.fromString((String)evidence.get(0).get("id"));
            if(mode.equals("bad")||mode.equals("repair")&&n==1)id=UUID.randomUUID();
            if(mode.startsWith("compact"))return JsonCodec.encode(new AnalysisService.ShortSynthesis("analysis-v1",new AnalysisService.ShortHypothesis("Possible takeover",mode.equals("compactbad")?"E99":"E1",List.of(),"MEDIUM","Review needed"),new AnalysisService.ShortRecommendation("REVIEW","Review cited login","E1","HIGH","Analyst approval")));
            if(p.purpose().equals("answer"))return JsonCodec.encode(new Answer("The case contains authentication events",List.of(id),List.of("Fixture interpretation")));
            return JsonCodec.encode(new AnalysisService.Synthesis("analysis-v1",List.of(new Hypothesis("Possible takeover",List.of(id),List.of(),"MEDIUM",List.of("Not causal proof"))),List.of(new AnalysisService.Recommendation("REVIEW","Review cited logins","HIGH",List.of(id),List.of("Analyst approval")))));
        };
        var analysis=new AnalysisService(llm,new TimelineBuilder(),new RuleSeverityPolicy(),store);var bus=new EventBus();
        engine=new AgentEngine(new RulePlanningStrategy(new PlanValidator(tools,store),store),tools,analysis,bus,store);
        c=new AgentController(engine,new JsonCaseRepository(temp.resolve("cases")),new LogImporter(store),new ReportService(),bus);
    }
    @AfterEach void close(){tools.close();}
    Investigation ready(){var inv=c.start(new Request("Investigate demo analyst",new CaseScope("demo",store.currentVersion(),"demo-analyst",time,time.plusSeconds(3600))),TargetType.ACCOUNT,"demo-feed-v1",true);return inv;}
    Investigation populated(){var inv=ready();c.importLogs(inv.snapshot().id(),Path.of("data/scenarios/account-takeover.json"));store.loadIndicatorFeed(Path.of("data/indicators/threat-feed.json"));c.acceptRulePlan(inv.snapshot().id());return inv;}
    @Test void fullRunRevisesPlanEnrichesAndFixesSevenPointSeverity(){var i=populated();var a=c.run(i.snapshot().id());assertEquals(CaseStatus.COMPLETED,i.snapshot().status());assertEquals(7,a.severity().score());assertEquals(SeverityLevel.HIGH,a.severity().level());assertEquals(List.of("R1","R2","R3"),a.severity().ruleIds());assertTrue(i.snapshot().plan().revision()>0);assertTrue(i.snapshot().evidence().size()>6);assertEquals(1,calls.get());assertFalse(a.hypotheses().isEmpty());}
    @Test void offlineModelPreservesDeterministicPartialResults(){mode="offline";var i=populated();var a=c.run(i.snapshot().id());assertEquals(CaseStatus.PARTIAL,i.snapshot().status());assertEquals(7,a.severity().score());assertTrue(a.hypotheses().isEmpty());assertTrue(a.recommendations().isEmpty());assertEquals(1,calls.get());}
    @Test void fabricatedCitationsAreRejectedAfterExactlyOneRepair(){mode="bad";var i=populated();var a=c.run(i.snapshot().id());assertEquals(2,calls.get());assertEquals(Completeness.PARTIAL,a.completeness());assertTrue(a.hypotheses().isEmpty());}
    @Test void oneCitationRepairCanSucceed(){mode="repair";var i=populated();assertEquals(Completeness.COMPLETE,c.run(i.snapshot().id()).completeness());assertEquals(2,calls.get());}
    @Test void emptyCoverageIsUndeterminedAndPartial(){var i=ready();mode="offline";var a=c.run(i.snapshot().id());assertEquals(SeverityLevel.UNDETERMINED,a.severity().level());assertEquals(Completeness.PARTIAL,a.completeness());}
    @Test void followupPersistsCitationsAndConversation(){var i=populated();c.run(i.snapshot().id());var a=c.ask(i.snapshot().id(),"Explain this case");assertFalse(a.evidenceIds().isEmpty());assertEquals(1,i.snapshot().conversation().size());c.save(i.snapshot().id());var opened=c.open(i.snapshot().id());assertEquals(a,opened.snapshot().conversation().get(0).answer());}
    @Test void followupScopeChangeIsRejectedAndRecorded(){var i=populated();assertThrows(IllegalArgumentException.class,()->c.ask(i.snapshot().id(),"Investigate all accounts"));assertEquals(0,calls.get());assertNotNull(i.snapshot().conversation().get(0).failure());}
    @Test void noEvidenceAnswerIsExplicitAndMakesNoModelCall(){var i=ready();var a=c.ask(i.snapshot().id(),"Explain this case");assertTrue(a.evidenceIds().isEmpty());assertEquals(0,calls.get());}
    @Test void ruleWeightsBoundariesAndMissingAuth(){var p=new RuleSeverityPolicy();assertEquals(SeverityLevel.UNDETERMINED,p.assess(new Facts(Map.of(),Map.of(),List.of())).level());for(int bits=0;bits<16;bits++){var m=new HashMap<String,Boolean>();m.put("AUTH",true);int expected=0;int[] w={2,3,2,1};for(int n=0;n<4;n++){m.put("R"+(n+1),(bits&(1<<n))!=0);if(m.get("R"+(n+1)))expected+=w[n];}var s=p.assess(new Facts(m,Map.of(),List.of()));assertEquals(expected,s.score());assertEquals(expected<=2?SeverityLevel.LOW:expected<=5?SeverityLevel.MEDIUM:SeverityLevel.HIGH,s.level());}}
    @Test void inventoryAddsOnePointOnlyForAffectedCriticalHost(){var i=populated();c.inventory(Set.of("workstation-1"));assertEquals(8,c.run(i.snapshot().id()).severity().score());}
    @Test void sparseOptionalFieldsDoNotCrashSeverity(){store.ingest(new ImportBatch(List.of(new Event("one",time,"login","demo-analyst",null,null,"success","fixture#/0","pending"))));var i=ready();var f=RuleSeverityPolicy.derive(store,i.snapshot(),Set.of(),false,false);assertFalse(f.predicates().get("AUTH"));assertTrue(f.limitations().stream().anyMatch(s->s.contains("unknown")));}
    @Test void timelineDeduplicatesSourceIdsAndOrdersTies(){var i=populated();var scope=i.snapshot().scope();var args=Map.of("datasetId","demo","datasetVersion",scope.datasetVersion(),"accountId",scope.target(),"start",scope.start().toString(),"end",scope.end().toString(),"limit","1000");var e=store.search(new ToolCall(UUID.randomUUID(),"logSearch",args)).evidence();var all=new ArrayList<>(e);all.addAll(e);var t=new TimelineBuilder();assertEquals(6,t.build(all).size());assertFalse(t.correlate(t.build(all)).isEmpty());}
    @Test void correlationsRespectFifteenMinuteBoundaryAndNullFields(){var t=new TimelineBuilder();Event a=new Event("a",time,"x","u",null,null,null,"a","v1"),b=new Event("b",time.plusSeconds(900),"x","u",null,null,null,"b","v1"),d=new Event("d",time.plusSeconds(901),"x",null,null,null,null,"d","v1");assertEquals(1,t.correlate(List.of(d,b,a)).size());}
    @Test void canonicalScopeExcludesOtherAccountFromTimeline(){var i=populated();assertTrue(new TimelineBuilder().build(store,i.snapshot()).isEmpty());c.run(i.snapshot().id());assertTrue(i.snapshot().assessment().timeline().stream().allMatch(e->e.accountId().equals("demo-analyst")));}
    @Test void datasetAndFeedRoundtripPreserveCanonicalEvidence(){var i=populated();c.run(i.snapshot().id());Path file=temp.resolve("data.json");store.save(file);var restored=new DatasetStore("demo");restored.restore(file);assertEquals(store.events("v1"),restored.events("v1"));for(var e:i.snapshot().evidence())assertTrue(restored.resolveEvent(e).isPresent()||restored.resolveIndicator(e).isPresent());}
    @Test void failedDurableImportLeavesPriorMemoryVersion(){var i=ready();Path blocked=temp.resolve("file");try{Files.writeString(blocked,"not a directory");}catch(Exception x){fail(x);}store.durable(blocked.resolve("data.json"));assertThrows(IllegalStateException.class,()->c.importLogs(i.snapshot().id(),Path.of("data/scenarios/account-takeover.json")));assertEquals("v0",store.currentVersion());assertEquals("v0",i.snapshot().scope().datasetVersion());}
    @Test void corruptedDatasetRestoreIsAtomic()throws Exception{var i=populated();Path file=temp.resolve("bad.json");store.save(file);String json=Files.readString(file).replace("\"schemaVersion\":1","\"schemaVersion\":99");Files.writeString(file,json);assertThrows(IllegalArgumentException.class,()->store.restore(file));assertEquals("v1",store.currentVersion());}
    @Test void repositoryRejectsStaleWritesAndUnknownFields()throws Exception{var i=ready();var repo=new JsonCaseRepository(temp.resolve("repo"));var old=i.snapshot();repo.save(old);i.recordAction("CHECK","OK",List.of());repo.save(i.snapshot());assertThrows(IllegalStateException.class,()->repo.save(old));Path p=temp.resolve("repo").resolve(old.id()+".json");Files.writeString(p,Files.readString(p).replaceFirst("\\{","{\"unexpected\":true,"));assertThrows(IllegalArgumentException.class,()->repo.load(old.id()));}
    @Test void runningRestoreBecomesPausedAndRequiresRevalidation(){var i=populated();i.recordAction("STATE_CHANGED","RUNNING",List.of());c.save(i.snapshot().id());var opened=c.open(i.snapshot().id());assertEquals(CaseStatus.PAUSED,opened.snapshot().status());assertThrows(IllegalStateException.class,()->c.run(opened.snapshot().id()));c.acceptRulePlan(opened.snapshot().id());assertEquals(CaseStatus.READY,opened.snapshot().status());}
    @Test void markdownExportRequiresExplicitOverwriteAndPreservesCase()throws Exception{var i=populated();mode="offline";c.run(i.snapshot().id());var before=i.snapshot();var r=new ReportService();Path file=temp.resolve("report.md");r.export(i,file);String text=Files.readString(file);assertTrue(text.contains("PARTIAL"));assertTrue(text.contains("provenance"));assertThrows(IllegalStateException.class,()->r.export(i,file));r.export(i,file,true);assertEquals(before,i.snapshot());}
    @Test void strictJsonRejectsDuplicateAndTrailingKeys(){assertThrows(IllegalArgumentException.class,()->JsonCodec.tree("{\"x\":1,\"x\":2}"));assertThrows(IllegalArgumentException.class,()->JsonCodec.tree("{}{}"));assertThrows(IllegalArgumentException.class,()->JsonCodec.decode("{}",CaseSnapshot.class));}
    @Test void dispatcherAndCliUseTheSameApplicationFlow(){var cli=new sentinel.presentation.SentinelCLI(c,new java.io.PrintStream(java.io.OutputStream.nullOutputStream()));var i=ready();c.save(i.snapshot().id());assertEquals("SUCCESS",cli.submit(new Action("show",Map.of())).status());assertEquals("SUCCESS",cli.submit(new Action("list",Map.of())).status());assertThrows(IllegalArgumentException.class,()->sentinel.presentation.SentinelCLI.parse(new String[]{"show","--case","x","--case","y"}));}

    @Test void invalidAnswerIsNeverCommittedButFailureSurvivesDispatcher(){mode="bad";var i=populated();mode="valid";c.run(i.snapshot().id());mode="bad";var dispatcher=new ActionDispatcher(c);assertThrows(IllegalArgumentException.class,()->dispatcher.submit(new Action("ask",Map.of("question","Explain this case"))));var restored=new JsonCaseRepository(temp.resolve("cases")).load(i.snapshot().id());assertNotNull(restored.snapshot().conversation().get(0).failure());assertNull(restored.snapshot().conversation().get(0).answer());}
    @Test void planningAndAnalysisShareSixCallBudget(){var i=populated();var analysis=new AnalysisService(p->{calls.incrementAndGet();throw new IllegalArgumentException("bad draft");},new TimelineBuilder(),new RuleSeverityPolicy(),store);
        PlanningStrategy planner=new PlanningStrategy(){public Plan createPlan(CaseContext ctx){throw new AssertionError();}public Plan createPlan(CaseContext ctx,ModelBudget budget){for(int n=0;n<6;n++)budget.acquire();return new RulePlanningStrategy(new PlanValidator(tools,store),store).createPlan(new CaseContext(ctx.snapshot(),true));}};
        var other=new AgentEngine(planner,tools,analysis,new EventBus(),store);other.plan(new Request(i.snapshot().goal(),i.snapshot().scope()),i);var a=other.run(i);assertEquals(0,calls.get());assertEquals(Completeness.PARTIAL,a.completeness());assertTrue(i.snapshot().history().stream().anyMatch(e->e.outcome().equals("BUDGET_EXHAUSTED")));}
    @Test void cancelledRunKeepsPartialDeterministicOutputWithoutInference(){var i=populated();tools.close();final AgentEngine[] holder=new AgentEngine[1];final UUID cancelId=i.snapshot().id();var observed=new LogSearchCommand(store);
        tools=new ToolExecutor(Map.of("logSearch",call->{holder[0].cancel(cancelId);return observed.execute(call);},"userActivity",new UserActivityCommand(store),"indicatorLookup",new IndicatorLookupCommand(store)));
        holder[0]=new AgentEngine(ctx->null,tools,new AnalysisService(p->{fail("Cancelled run must not call model");return "";},new TimelineBuilder(),new RuleSeverityPolicy(),store),new EventBus(),store);
        var result=holder[0].run(i);assertEquals(Completeness.PARTIAL,result.completeness());assertEquals(CaseStatus.PARTIAL,i.snapshot().status());assertEquals(6,result.timeline().size());}
    @Test void failedToolRetainsAcceptedEvidenceAndPartialAssessment(){var i=populated();tools.close();tools=new ToolExecutor(Map.of("logSearch",new LogSearchCommand(store),"userActivity",call->{throw new ToolException(ToolException.Code.EXECUTION_FAILED,"fixture");},"indicatorLookup",new IndicatorLookupCommand(store)));
        var e=new AgentEngine(ctx->null,tools,new AnalysisService(p->{throw new ModelException(ModelException.Code.UNAVAILABLE,"offline");},new TimelineBuilder(),new RuleSeverityPolicy(),store),new EventBus(),store);var a=e.run(i);assertEquals(6,a.timeline().size());assertEquals(Completeness.PARTIAL,a.completeness());assertFalse(i.snapshot().evidence().isEmpty());}
    @Test void failedFeedPersistenceDoesNotPublishNewFeed()throws Exception{Path file=temp.resolve("blocked");Files.writeString(file,"x");store.durable(file.resolve("x.json"));assertThrows(IllegalStateException.class,()->store.loadIndicatorFeed(Path.of("data/indicators/threat-feed.json")));assertThrows(ToolException.class,()->store.lookup(new ToolCall(UUID.randomUUID(),"indicatorLookup",Map.of("indicator","192.0.2.10","feedVersion","demo-feed-v1"))));}
    @Test void conflictingTimelineSourceIdsAreFlagged(){var a=new Event("a",time,"login","u",null,null,"success","p","v1");var b=new Event("a",time.plusSeconds(1),"login","u",null,null,"success","p","v1");var e1=new Evidence(UUID.randomUUID(),"a","v1","p",JsonCodec.encode(a));var e2=new Evidence(UUID.randomUUID(),"a","v1","p",JsonCodec.encode(b));assertThrows(IllegalArgumentException.class,()->new TimelineBuilder().build(List.of(e1,e2)));}

    @Test void compactReferencesResolveToCanonicalEvidenceIds(){mode="compact";var i=populated();var a=c.run(i.snapshot().id());assertEquals(Completeness.COMPLETE,a.completeness());assertEquals(i.snapshot().evidence().get(0).id(),a.hypotheses().get(0).supportingEvidenceIds().get(0));}
    @Test void unknownCompactReferenceIsRejectedAfterOneRepair(){mode="compactbad";var i=populated();var a=c.run(i.snapshot().id());assertEquals(Completeness.PARTIAL,a.completeness());assertEquals(2,calls.get());assertTrue(a.hypotheses().isEmpty());}
    @Test void compactCitationValidatorUsesTheSameProductionParser(){mode="compact";var i=populated();c.run(i.snapshot().id());var reply=JsonCodec.encode(new AnalysisService.ShortSynthesis("analysis-v1",new AnalysisService.ShortHypothesis("Possible takeover","E1",List.of(),"LOW","Uncertain"),new AnalysisService.ShortRecommendation("REVIEW","Review","E1","LOW","Approval")));var service=new AnalysisService(p->"",new TimelineBuilder(),new RuleSeverityPolicy(),store);assertTrue(service.validateCitations(reply,i));assertFalse(service.validateCitations(reply.replace("E1","E99"),i));}

    @Test void pausedPlanAtRevisionCeilingCanBeRevalidatedWithoutNewPlanning(){var i=populated();var old=i.snapshot().plan();i.setPlan(new Plan(UUID.randomUUID(),2,old.steps(),old.dependencies(),old.origin()));i.recordAction("STATE_CHANGED","RUNNING",List.of());c.save(i.snapshot().id());var opened=c.open(i.snapshot().id());assertEquals(CaseStatus.PAUSED,opened.snapshot().status());var same=opened.snapshot().plan();c.resume(opened.snapshot().id());assertEquals(same,opened.snapshot().plan());assertEquals(CaseStatus.READY,opened.snapshot().status());assertEquals(0,calls.get());assertEquals(2,opened.snapshot().plan().revision());}
}
